'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isInfinite = require( '@stdlib/math/base/assert/is-infinite' );
var abs = require( '@stdlib/math/base/special/abs' );
var ceil = require( '@stdlib/math/base/special/ceil' );
var floor = require( '@stdlib/math/base/special/floor' );
var log10 = require( '@stdlib/math/base/special/log10' );
var ln = require( '@stdlib/math/base/special/ln' );
var pow = require( '@stdlib/math/base/special/pow' );


// MAIN //

/**
* Rounds a numeric value to the nearest number toward positive infinity with `n` significant figures.
*
* @param {number} x - input value
* @param {PositiveInteger} n - number of significant figures
* @param {PositiveInteger} [b=10] - base
* @returns {number} rounded value
*
* @example
* var v = roundsdf( 3.141592653589793, 3 );
* // returns 3.15
*
* @example
* var v = roundsdf( 3.141592653589793, 1 );
* // returns 4.0
*
* @example
* var v = roundsdf( 12368.0, 2 );
* // returns 13000.0
*
* @example
* var v = roundsdf( 0.0313, 2, 2 );
* // returns 0.046875
*/
function roundsdf( x, n, b ) {
	var base;
	var e;
	var s;

	if ( isnan( x ) || isnan( n ) || n < 1 || isInfinite( n ) ) {
		return NaN;
	}
	if ( isInfinite( x ) || x === 0.0 ) {
		return x;
	}
	if ( b === void 0 ) {
		base = 10.0;
	} else if ( isnan( b ) || b < 1 || isInfinite( b ) ) {
		return NaN;
	} else {
		base = b;
	}

	// If base is 10, use optimized log10 path:
	if ( base === 10.0 ) {
		// Base-10 exponent:
		e = floor( log10( abs( x ) ) - n + 1.0 );

		// Scale factor:
		s = pow( 10.0, abs( e ) );

		if ( e < 0 ) {
			return ceil( x * s ) / s;
		}
		return ceil( x / s ) * s;
	}
	// For other bases, use natural logarithm:
	e = floor( ( ln( abs( x ) ) / ln( base ) ) - n + 1.0 );

	// Scale factor:
	s = pow( base, abs( e ) );

	if ( e < 0 ) {
		return ceil( x * s ) / s;
	}
	return ceil( x / s ) * s;
}


// EXPORTS //

module.exports = roundsdf;
